    "slot_number": "slot-4-3-2",
    "slot_key": "Partial submission and recovery rules",
    "slot_value": "Keep the dossier in a pending state, show the supplier it has not been accepted yet, and retry or resume without losing the evidence package. Retries are needed for reliability, but the retry window must be balanced against failing fast and telling the supplier to intervene manually.",
    "operation": "refine"
  }
]

[
