  },
  {
    "slot_number": "slot-8-2-2",
    "slot_key": "Fault tolerance and recovery expectations",
    "slot_value": "If the service is down or delivery is uncertain, keep the dossier pending, show the supplier it has not been accepted yet, and retry or resume without losing the evidence package; retrying should balance against failing fast and telling the supplier to intervene manually so automation does not hide problems or make the process too fragile.",
    "operation": "refine"
  }
]

[
